CREATE OR REPLACE FUNCTION lab.code_kind (p_code varchar)
RETURNS varchar
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
BEGIN
  /* O2PG-REVIEW O2PG-RV-034: '' is NULL in Oracle but an empty string in PostgreSQL; comparisons with '' and assignments of '' behave differently */
  IF p_code = '' THEN
    RETURN 'empty';
  ELSIF p_code IS NULL THEN
    RETURN 'missing';
  ELSE
    RETURN 'value';
  END IF;
END;
$$;
